def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    gaps = {}
    for r, row in enumerate(grid):
        # A missing cell inside a horizontal run marks the color to project upward.
        for c in range(1, w - 1):
            if row[c] == 0 and row[c - 1] != 0 and row[c + 1] != 0:
                color = row[c - 1]
                gaps.setdefault(c, []).append((r, color))
                g[r][c] = color
    # Each successive horizontal gap colors the vertical interval above it.
    for c, marks in gaps.items():
        marks.sort()
        previous = -1
        for r, color in marks:
            for rr in range(previous + 1, r):
                g[rr][c] = color
            previous = r
    # Extend vertical colored stems upward to the lowest horizontal bar.
    bars = [r for r, row in enumerate(grid) if sum(v != 0 for v in row) >= 3]
    for c in range(w):
        r = h - 1
        while r >= 0 and grid[r][c] == 0:
            r -= 1
        if r < 0:
            continue
        color = grid[r][c]
        if r == h - 1 or any(grid[rr][c] == color for rr in range(r + 1, h)):
            # Find the contiguous stem's top, anchored in the bottom portion.
            top = r
            while top > 0 and grid[top - 1][c] == color:
                top -= 1
            if top > 0 and top >= max(0, h - 6):
                stop = max((br for br in bars if br < top), default=-1)
                for rr in range(stop + 1, top):
                    if g[rr][c] == 0:
                        g[rr][c] = color
    return g
